const aiResponse = $json;

const source =
  $('Подготовить запрос Semantic Aggregator').item.json;


// ============================================================
// 1. Проверяем технический ответ API
// ============================================================

const choice =
  aiResponse?.choices?.[0];

if (!choice) {
  throw new Error(
    '[Semantic Aggregator Validator] В ответе отсутствует choices[0]'
  );
}

if (choice.finish_reason !== 'stop') {
  throw new Error(
    `[Semantic Aggregator Validator] Некорректный finish_reason: ${choice.finish_reason}`
  );
}

const content =
  choice?.message?.content;

if (
  typeof content !== 'string' ||
  !content.trim()
) {
  throw new Error(
    '[Semantic Aggregator Validator] message.content пуст'
  );
}


// ============================================================
// 2. Парсим JSON модели
// ============================================================

let result;

try {
  result = JSON.parse(content);
} catch (error) {
  throw new Error(
    `[Semantic Aggregator Validator] Модель вернула невалидный JSON: ${error.message}`
  );
}


// ============================================================
// 3. Разрешённые значения
// ============================================================

const ALLOWED_STATUSES =
  new Set([
    'resolved',
    'requires_recheck',
  ]);

const ALLOWED_ROLES =
  new Set([
    'primary',
    'duplicate',
    'supporting',
    'complement',
    'conflict',
    'not_applicable',
  ]);

const ALLOWED_RECHECK_CODES =
  new Set([
    'conflicting_candidates',
    'insufficient_evidence',
    'ambiguous_scope',
    'no_reliable_candidate',
    'other',
  ]);


// ============================================================
// 4. Проверяем field_key
// ============================================================

if (result.field_key !== source.field_key) {
  throw new Error(
    `[Semantic Aggregator Validator] field_key изменён: ожидался ${source.field_key}, получен ${result.field_key}`
  );
}


// ============================================================
// 5. Проверяем status
// ============================================================

if (!ALLOWED_STATUSES.has(result.status)) {
  throw new Error(
    `[Semantic Aggregator Validator] Недопустимый status: ${result.status}`
  );
}


// ============================================================
// 6. Проверяем confidence
// ============================================================

if (
  typeof result.confidence !== 'number' ||
  !Number.isFinite(result.confidence) ||
  result.confidence < 0 ||
  result.confidence > 1
) {
  throw new Error(
    `[Semantic Aggregator Validator] Некорректный confidence: ${result.confidence}`
  );
}


// ============================================================
// 7. Проверяем candidate_decisions
// ============================================================

if (!Array.isArray(result.candidate_decisions)) {
  throw new Error(
    '[Semantic Aggregator Validator] candidate_decisions должен быть массивом'
  );
}

const allowedFactIds =
  Array.isArray(source.allowed_fact_ids)
    ? source.allowed_fact_ids
    : [];

const allowedFactIdSet =
  new Set(allowedFactIds);

if (
  result.candidate_decisions.length !==
  allowedFactIds.length
) {
  throw new Error(
    `[Semantic Aggregator Validator] Ожидалось ${allowedFactIds.length} candidate_decisions, получено ${result.candidate_decisions.length}`
  );
}

const usedFactIds =
  new Set();

const decisionByFactId =
  new Map();

for (const decision of result.candidate_decisions) {

  if (
    typeof decision?.fact_id !== 'string' ||
    !decision.fact_id
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] candidate_decision без fact_id'
    );
  }

  if (!allowedFactIdSet.has(decision.fact_id)) {
    throw new Error(
      `[Semantic Aggregator Validator] Модель придумала неизвестный fact_id: ${decision.fact_id}`
    );
  }

  if (usedFactIds.has(decision.fact_id)) {
    throw new Error(
      `[Semantic Aggregator Validator] fact_id повторяется: ${decision.fact_id}`
    );
  }

  usedFactIds.add(
    decision.fact_id
  );

  if (!ALLOWED_ROLES.has(decision.role)) {
    throw new Error(
      `[Semantic Aggregator Validator] Недопустимая role=${decision.role} для fact_id=${decision.fact_id}`
    );
  }

  if (
    typeof decision.reason !== 'string' ||
    !decision.reason.trim()
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Нет reason для fact_id=${decision.fact_id}`
    );
  }

  decisionByFactId.set(
    decision.fact_id,
    decision
  );
}


// ============================================================
// 8. Убеждаемся, что ни один входной fact не потерян
// ============================================================

for (const factId of allowedFactIds) {
  if (!usedFactIds.has(factId)) {
    throw new Error(
      `[Semantic Aggregator Validator] В ответе потерян fact_id=${factId}`
    );
  }
}


// ============================================================
// 9. Проверяем supporting_fact_ids
// ============================================================

if (!Array.isArray(result.supporting_fact_ids)) {
  throw new Error(
    '[Semantic Aggregator Validator] supporting_fact_ids должен быть массивом'
  );
}

const supportingSet =
  new Set();

for (const factId of result.supporting_fact_ids) {

  if (!allowedFactIdSet.has(factId)) {
    throw new Error(
      `[Semantic Aggregator Validator] Неизвестный supporting fact_id=${factId}`
    );
  }

  if (supportingSet.has(factId)) {
    throw new Error(
      `[Semantic Aggregator Validator] Дубликат supporting fact_id=${factId}`
    );
  }

  supportingSet.add(factId);

  const role =
    decisionByFactId.get(factId)?.role;

  if (
    role === 'conflict' ||
    role === 'not_applicable'
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] fact_id=${factId} имеет role=${role}, но указан как supporting`
    );
  }
}


// ============================================================
// 10. Проверяем conflict_fact_ids
// ============================================================

if (!Array.isArray(result.conflict_fact_ids)) {
  throw new Error(
    '[Semantic Aggregator Validator] conflict_fact_ids должен быть массивом'
  );
}

const conflictSet =
  new Set();

for (const factId of result.conflict_fact_ids) {

  if (!allowedFactIdSet.has(factId)) {
    throw new Error(
      `[Semantic Aggregator Validator] Неизвестный conflict fact_id=${factId}`
    );
  }

  if (conflictSet.has(factId)) {
    throw new Error(
      `[Semantic Aggregator Validator] Дубликат conflict fact_id=${factId}`
    );
  }

  conflictSet.add(factId);
}


// Все role=conflict обязаны находиться в conflict_fact_ids
for (const decision of result.candidate_decisions) {

  const listedAsConflict =
    conflictSet.has(decision.fact_id);

  if (
    decision.role === 'conflict' &&
    !listedAsConflict
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] fact_id=${decision.fact_id} имеет role=conflict, но отсутствует в conflict_fact_ids`
    );
  }

  if (
    decision.role !== 'conflict' &&
    listedAsConflict
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] fact_id=${decision.fact_id} указан в conflict_fact_ids, но role=${decision.role}`
    );
  }
}


// ============================================================
// 11. Проверяем согласованность resolved / requires_recheck
// ============================================================

const primaryCount =
  result.candidate_decisions.filter(
    decision =>
      decision.role === 'primary'
  ).length;


if (result.status === 'resolved') {

  if (
    typeof result.final_value_text !== 'string' ||
    !result.final_value_text.trim()
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Для resolved требуется final_value_text'
    );
  }

  if (result.needs_recheck !== false) {
    throw new Error(
      '[Semantic Aggregator Validator] Для resolved needs_recheck должен быть false'
    );
  }

  if (result.recheck_reason_code !== null) {
    throw new Error(
      '[Semantic Aggregator Validator] Для resolved recheck_reason_code должен быть null'
    );
  }

  if (primaryCount !== 1) {
    throw new Error(
      `[Semantic Aggregator Validator] Для resolved ожидается ровно один primary, получено ${primaryCount}`
    );
  }

  if (conflictSet.size > 0) {
    throw new Error(
      '[Semantic Aggregator Validator] resolved не может содержать unresolved conflict'
    );
  }
}


if (result.status === 'requires_recheck') {

  if (result.needs_recheck !== true) {
    throw new Error(
      '[Semantic Aggregator Validator] Для requires_recheck needs_recheck должен быть true'
    );
  }

  if (
    !ALLOWED_RECHECK_CODES.has(
      result.recheck_reason_code
    )
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Некорректный recheck_reason_code: ${result.recheck_reason_code}`
    );
  }

  if (
    typeof result.recheck_note !== 'string' ||
    !result.recheck_note.trim()
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Для requires_recheck нужен recheck_note'
    );
  }

  if (primaryCount > 1) {
    throw new Error(
      `[Semantic Aggregator Validator] Для requires_recheck не может быть больше одного primary, получено ${primaryCount}`
    );
  }
}


// ============================================================
// 12. Возвращаем проверенный результат + provenance
// ============================================================

return {
  json: {
    analysis_run_id:
      source.analysis_run_id,

    field_catalog_version:
      source.field_catalog_version,

    field_index:
      source.field_index,

    field_key:
      source.field_key,

    aggregation_status:
      result.status,

    final_value_text:
      result.final_value_text ?? null,

    confidence:
      result.confidence,

    candidate_decisions:
      result.candidate_decisions,

    supporting_fact_ids:
      result.supporting_fact_ids,

    conflict_fact_ids:
      result.conflict_fact_ids,

    needs_recheck:
      result.needs_recheck,

    recheck_reason_code:
      result.recheck_reason_code,

    recheck_note:
      result.recheck_note,

    aggregation_input:
      source.aggregation_input,

    semantic_aggregator_meta: {
      response_id:
        aiResponse.id ?? null,

      model:
        aiResponse.model ?? null,

      finish_reason:
        choice.finish_reason,

      usage:
        aiResponse.usage ?? null,
    },

    aggregation_validated: true,
  },
};

