  for (const item of candidateEvidence) {
    evidence.push({
      ...item,

      candidate_ref:
        `fact:${decision.fact_id}`,

      candidate_role:
        decision.role,

      candidate_origin:
        'initial_analysis',

      candidate_value_text:
        candidate.value_text ?? null,
    });
  }
}


// ============================================================
